vec3 ballFront(vec2 uv)
{
    float face = floor(uv.x);
    float x = fract(uv.x) * 2. - 1.;
    float y = uv.y * 2. - 1.;

    if (face == 0.)
        return vec3(-1, y, -x);
    if (face == 1.)
        return vec3(x, y, -1);
    //if (face == 2.)
        return vec3(1, y, x);
}

vec3 ballBack(vec2 uv)
{
    return -ballFront(uv).yxz;
}

vec3 ball(vec2 uv)
{
    uv *= vec2(3, 2);
    return uv.y < 1. ? ballFront(uv) : ballBack(uv - vec2(0, 1));
}

float f;
vec2 uv;
vec3 C = vec3(1);

mat2 R(float a) { return mat2(cos(a), sin(a), -sin(a), cos(a)); }
void front()
{
    vec2 q = uv - vec2(1.5, .5);
    if (abs(q.x) < 1.5 && abs(q.y) < .5)
        C = pow(texture(iChannel0, ballFront(q + vec2(1.5, .5))).xyz, vec3(2.));
    q = abs(q) - vec2(1.5, .5);
    C = mix(C, vec3(0), clamp(1. - f * abs(length(max(q, 0.)) + min(max(q.x, q.y), 0.)), 0., 1.));
}

void back(vec2 x, vec2 o, float a)
{
    vec2 q = (uv - x) * R(a) + o;
    if (abs(q.x) < 1.5 && abs(q.y) < .5)
        C = pow(texture(iChannel0, ballBack(q + vec2(1.5, .5))).xyz, vec3(2.));
    q = abs(q) - vec2(1.5, .5);
    C = mix(C, vec3(0), clamp(1. - f * abs(length(max(q, 0.)) + min(max(q.x, q.y), 0.)), 0., 1.));
    C = mix(C, vec3(1,0,0), clamp(3. - f * length(uv - x), 0., 1.));
}

vec2 box(float s)
{
    s = s - floor(s / 8.) * 8.;
    if (s < 3.)
        return vec2(s, 0);
    if (s < 4.)
        return vec2(3, s - 3.);
    if (s < 7.)
        return vec2(7. - s, 1);
    //if (s < 8.)
        return vec2(0, 8. - s);
}

void mainImage(out vec4 fragColor, vec2 fragCoord)
{
    uv = fragCoord / iResolution.xy;
    C = mix(vec3(1), pow(texture(iChannel0, ball(uv), -8.).xyz, vec3(2.)), .2);

    float t = iTime + 6.7;
    if (iMouse.z > 0.) t += (iMouse.x - abs(iMouse.z)) / iResolution.x * 20.;
    float pivot = floor(t) + smoothstep(.5, 1., fract(t));
    float angle = floor(t) + smoothstep(0., .5, fract(t)); angle = radians(-90. * angle);
    vec2 x = box(4. - pivot);

    f = iResolution.y / 3.1;
    uv = (fragCoord - iResolution.xy / 2.) / f;
    uv += vec2(1.5, .5);
    //uv *= R(-angle / 2.);
    //uv += x;
    front();
    //for (float i=0.; i<4. ; i++, t+=2.)
    {
        float pivot = floor(t) + smoothstep(.5, 1., fract(t));
        float angle = floor(t) + smoothstep(0., .5, fract(t)); angle = radians(-90. * angle);
        vec2 x = box(4. - pivot);
        back(x, box(1. + pivot) - vec2(1.5, .5), angle);
    }
    fragColor = vec4(sqrt(C), 1);
}
